def brute_force_search(text: str, patterns: Sequence[str]) -> list[tuple[int, str]]:
    """O(n * m * k) naive scan — for reference only.  Deduplicates patterns."""
    seen: set[str] = set()
    unique: list[str] = []
    for p in patterns:
        if p and p not in seen:
            seen.add(p)
            unique.append(p)
    results: list[tuple[int, str]] = []
    for pattern in unique:
        k = len(pattern)
        for i in range(len(text) - k + 1):
            if text[i : i + k] == pattern:
                results.append((i, pattern))
    results.sort()
    return results
